struct rangeElement *parseIntRanges(const char *text)
{
    int state = 0;
    int flag_dash = 0x01;
    int i;
    char numbuf[1024];
    int numbufi;
    struct rangeElement *rv = ((void *)0);
    int start = 0;
    int end = 0;
    memset(numbuf, 0, sizeof(numbuf));
    numbufi = 0;
    for (i = 0; i < strlen(text); i++)
    {
        if (text[i] >= '0' && text[i] <= '9')
        {
            numbuf[numbufi] = text[i];
            numbufi++;
        }
        else if (text[i] == '-')
        {
            if (state & flag_dash)
            {
                fprintf(stderr, "error: too many dashes in range\n");
                exit(-1);
            }
            state |= flag_dash;
            if (numbufi == 0)
            {
                fprintf(stderr, "error: range cannot start with '-'\n");
                exit(-1);
            }
            start = atoi(numbuf);
            if (start <= 0)
            {
                fprintf(stderr, "error: start range <= 0\n");
                exit(-1);
            }
            memset(numbuf, 0, sizeof(numbuf));
            numbufi = 0;
        }
        else if (text[i] == ',')
        {
            if (numbufi == 0)
            {
                if (flag_dash)
                {
                    rv = rangeAddGreaterEqual(start, rv);
                }
            }
            else if (start > 0)
            {
                end = atoi(numbuf);
                if (end <= 0 || start > end)
                {
                    fprintf(stderr, "error: illegal start/end ranges\n");
                    exit(-1);
                }
                rv = rangeAddStartEnd(start, end, rv);
            }
            else
            {
                start = atoi(numbuf);
                rv = rangeAddSingle(start, rv);
            }
            memset(numbuf, 0, sizeof(numbuf));
            numbufi = 0;
            start = 0;
            end = 0;
            state = 0;
        }
    }
    if (numbufi == 0)
    {
        if (flag_dash)
        {
            rv = rangeAddGreaterEqual(start, rv);
        }
    }
    else if (start > 0)
    {
        end = atoi(numbuf);
        if (end <= 0 || start > end)
        {
            fprintf(stderr, "error: illegal start/end range %s\n", text);
            exit(-1);
        }
        rv = rangeAddStartEnd(start, end, rv);
    }
    else
    {
        start = atoi(numbuf);
        rv = rangeAddSingle(start, rv);
    }
    return rv;
}

