int getField(char *buf, int buflen, int *end, _Bool *inQuoted)
{
    _Bool bquoted = *inQuoted;
    for (*end = 0; *end < buflen; *end += 1)
    {
        char c = buf[*end];
        if (!gpAllowBinaryFlag && isBinChar(c))
        {
            fprintf(stderr, "error: line(%d): binary character (%d) found.  Use flag to ignore/pass\n", gLineCnt,
                    (int)c);
            exit(-1);
        }
        if (*inQuoted)
        {
            if (c == gpQuoteIn)
            {
                *inQuoted = 0;
            }
        }
        else
        {
            if (c == gpQuoteIn)
            {
                *inQuoted = 1;
            }
            if (c == gpDelimIn)
            {
                return rvDelim;
            }
            if (c == '\r')
            {
                return rvStateEOL;
            }
            if (c == '\n')
            {
                return rvStateEOL;
            }
            if (c == '\0' && *end == buflen - 1)
            {
                return rvStateEOL;
            }
        }
    }
    return rvStateEOL;
}

